"""Stage 8: what changed, and nothing else.

If a run turns up nothing new it says so in one line, which is a complete answer.
"""

from .scoring import ROUTES

LABEL = {"act": "Act", "test": "Test", "watch": "Watch",
         "reference": "Reference", "reject": "Reject", "notmine": "Not mine"}


def since(items, timestamp):
    out = []
    for it in items:
        if it.get("status") != "decided":
            continue
        if timestamp and (it.get("decided_at") or "") <= timestamp:
            continue
        out.append(it)
    return out


def render(items, timestamp=None):
    fresh = since(items, timestamp)
    if not fresh:
        return "Nothing new since the last digest."

    lines = []
    for r in ROUTES:
        group = [i for i in fresh if i.get("route") == r]
        if not group:
            continue
        lines.append("%s (%d)" % (LABEL[r], len(group)))
        for it in sorted(group, key=lambda x: x.get("decided_at") or ""):
            name = it.get("what") or it.get("name") or it.get("id")
            reason = it.get("reason")
            lines.append("  - %s%s" % (name, ("  (%s)" % reason) if reason else ""))
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"

"""Stages 6 and 7: score against the profile, then route.

Pure functions over data. No model, no network, no randomness, so the same item
and the same profile always produce the same route and the same reason.
"""

ROUTES = ("act", "test", "watch", "reference", "reject", "notmine")

VETOES = {
    "legal": "no lawful path to the intended use",
    "data": "unacceptable exposure of data or credentials",
    "licence": "the licence does not permit the intended use",
    "lockin": "no export or rollback for something that holds your data",
    "claims": "the economics rest entirely on unverified claims",
}

HELP = ("lot", "some", "little")
COST = ("hour", "day", "week")


class ScoringError(ValueError):
    pass


def goal_by_id(profile, goal_id):
    for g in (profile or {}).get("goals", []):
        if g.get("id") == goal_id:
            return g
    return None


def route(item, profile):
    """Return (route, reason). An empty route means not enough has been answered."""
    vetoes = [v for v in item.get("vetoes", []) if v in VETOES]
    if vetoes:
        return "reject", "a dealbreaker applies: %s" % VETOES[vetoes[0]]

    goal_id = item.get("goal") or ""
    if goal_id == "notmine":
        return "notmine", "it belongs to someone else"
    if goal_id in ("", "none"):
        if goal_id == "none":
            return "reference", "it does not serve a goal you have written down"
        return "", ""

    goal = goal_by_id(profile, goal_id)
    if goal is None:
        return "", ""
    name = '"%s"' % goal.get("name", goal_id)

    help_, cost = item.get("help"), item.get("cost")
    if help_ not in HELP or cost not in COST:
        return "", ""

    if help_ == "lot" and cost == "hour":
        return "act", "it helps %s a lot and costs about an hour to try" % name
    if help_ == "lot":
        return "test", "it helps %s a lot but is not a same-day job" % name
    if help_ == "some" and cost == "hour":
        return "test", "cheap enough to try against %s" % name
    if help_ == "some":
        return "watch", "some help to %s, not enough for the effort now" % name
    return "reference", "little help to %s as things stand" % name


def apply_route(item, profile, chosen=None, reason=None):
    suggested, why = route(item, profile)
    final = chosen or suggested
    if not final:
        raise ScoringError(
            "not enough answered to route this item. Set a goal, and help and cost.")
    if final not in ROUTES:
        raise ScoringError("unknown route %r. One of: %s" % (final, ", ".join(ROUTES)))
    item["route"] = final
    item["reason"] = (reason or item.get("reason") or why or "").strip()
    item["status"] = "decided"
    from . import store
    item["decided_at"] = store.now()
    return item


def counts(items):
    out = dict((r, 0) for r in ROUTES)
    for it in items:
        if it.get("route") in out:
            out[it["route"]] += 1
    return out

"""Best-effort PDF text extraction, with no dependencies.

This handles the common case: a PDF whose pages carry text in Flate-compressed
content streams. It does not handle scanned pages, which contain no text at all,
and it will not always survive unusual font encodings.

That is why every extraction is graded before it is used. A PDF that yields
garbage is reported as unreadable rather than passed on as if it were text,
because feeding noise to the reading stage is worse than admitting the gap.
"""

import re
import zlib

# Text-showing operators. Tj and ' take one string; TJ takes an array of strings
# and kerning numbers; " takes two numbers then a string.
_TEXT_OPS = re.compile(rb"(\((?:\\.|[^\\()])*\)|\[(?:[^\[\]\\]|\\.)*\])\s*(TJ|Tj|'|\")")
_STRING = re.compile(rb"\((?:\\.|[^\\()])*\)")

_ESCAPES = {
    b"n": b"\n",
    b"r": b"\r",
    b"t": b"\t",
    b"b": b"\x08",
    b"f": b"\x0c",
    b"(": b"(",
    b")": b")",
    b"\\": b"\\",
}


def _unescape(raw):
    """Resolve PDF string escapes, including octal character codes."""
    out = bytearray()
    i, n = 0, len(raw)
    while i < n:
        c = raw[i:i + 1]
        if c != b"\\":
            out += c
            i += 1
            continue
        nxt = raw[i + 1:i + 2]
        if nxt in _ESCAPES:
            out += _ESCAPES[nxt]
            i += 2
        elif nxt.isdigit():
            digits = b""
            j = i + 1
            while j < n and len(digits) < 3 and raw[j:j + 1].isdigit():
                digits += raw[j:j + 1]
                j += 1
            try:
                out.append(int(digits, 8) & 0xFF)
            except ValueError:
                pass
            i = j
        elif nxt == b"\n":
            i += 2                      # line continuation, emits nothing
        else:
            out += nxt
            i += 2
    return bytes(out)


def _streams(data):
    """Yield each decompressed content stream we can get at."""
    for match in re.finditer(rb"stream\r?\n", data):
        start = match.end()
        end = data.find(b"endstream", start)
        if end == -1:
            continue
        blob = data[start:end]
        try:
            yield zlib.decompress(blob)
        except zlib.error:
            # Uncompressed, or a filter we do not implement. Only useful raw if
            # it actually looks like a content stream.
            if _TEXT_OPS.search(blob):
                yield blob


def _is_content(stream):
    """True for a stream that draws text, false for metadata and font blobs."""
    return b"BT" in stream and (b"Tj" in stream or b"TJ" in stream)


def _text_from_stream(stream):
    """Every string in a content stream, in order, with no separator inserted.

    Separators are deliberately not added between strings. A PDF splits words
    across strings for kerning, so joining with a space turns "December 18,
    2023" into two fragments. Real word spacing is already inside the strings.
    """
    return [_unescape(s[1:-1]) for s in _STRING.findall(stream)]


def looks_like_text(text, min_chars=40, min_printable=0.80, min_letters=0.35):
    """Grade an extraction. False means: do not pretend this is readable."""
    if not text or len(text) < min_chars:
        return False
    printable = sum(1 for ch in text if ch.isprintable() or ch in "\n\t ")
    if printable / float(len(text)) < min_printable:
        return False
    letters = sum(1 for ch in text if ch.isalpha())
    return letters / float(len(text)) >= min_letters


def extract(data, limit=20000):
    """Return extracted text, or an empty string when nothing trustworthy came out."""
    parts = []
    total = 0
    for stream in _streams(data):
        if not _is_content(stream):
            continue
        for chunk in _text_from_stream(stream):
            parts.append(chunk)
            total += len(chunk)
        if total > limit * 3:
            break
    if not parts:
        return ""

    text = b"".join(parts).decode("latin-1", "replace")
    text = re.sub(r"[ \t]{2,}", " ", text)
    text = re.sub(r"\s*\n\s*", "\n", text)
    text = text.strip()
    if not looks_like_text(text):
        return ""
    return text[:limit]

"""Stage 1 and 3: get things in, and merge what is the same thing.

Deterministic, offline, no model. Deduplication is on the bytes for files and on
a normalised URL for links, so the same repository saved four times is one item.
"""

import json
import os

from . import pdftext, store

TEXT_EXT = {".txt", ".md", ".markdown", ".csv", ".tsv", ".json", ".log", ".rst"}

# Files that are almost certainly credentials. Cyft copies what it takes in and,
# on `cyft read`, sends the text to a model provider. Sweeping a project folder
# must not put a private key on the wire, so these are refused and named.
SECRET_EXT = {".pem", ".key", ".p12", ".pfx", ".jks", ".keystore", ".ppk", ".asc", ".gpg"}
SECRET_NAMES = {
    "id_rsa", "id_dsa", "id_ecdsa", "id_ed25519", "credentials", "credentials.json",
    "netrc", "pgpass", "htpasswd", "secrets.json", "secrets.yaml", "secrets.yml",
    "keyfile", "keystore",
}
SECRET_PREFIXES = ("id_rsa", "id_dsa", "id_ecdsa", "id_ed25519", "service-account",
                   "serviceaccount", "gcp-key", "aws-credentials")
SECRET_DIRS = {".ssh", ".gnupg", ".aws", ".kube", ".docker", "gcloud"}
IMAGE_EXT = {".png", ".jpg", ".jpeg", ".gif", ".webp"}
URLLIST_EXT = {".url", ".webloc", ".urls"}
SKIP_NAMES = {".DS_Store", "Thumbs.db"}

MEDIA_TYPES = {
    ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg",
    ".gif": "image/gif", ".webp": "image/webp",
}


def looks_like_secret(path):
    """Return why this file should not be taken in, or None if it is ordinary.

    Deliberately conservative about what it names: a false positive costs one
    skipped file and a printed reason, while a false negative can put a private
    key into a request body.
    """
    name = os.path.basename(path)
    lower = name.lower()

    # A credential dotfile is the same file with a dot in front of it, and
    # SECRET_NAMES holds the bare forms. Match on the name with leading dots
    # removed, or `.netrc` slips past `netrc` and is treated as ordinary, which
    # for a file named directly on the command line means it gets taken in.
    bare = lower.lstrip(".")
    stem, ext = os.path.splitext(bare)

    parts = os.path.normpath(path).split(os.sep)
    for part in parts[:-1]:
        if part.lower() in SECRET_DIRS:
            return "it is inside %s" % part

    if ext in SECRET_EXT:
        return "%s files hold keys or certificates" % ext
    if bare in SECRET_NAMES or stem in SECRET_NAMES:
        return "%s is a credential file" % name
    if lower.startswith(".env"):
        return "dotenv files hold secrets"
    for prefix in SECRET_PREFIXES:
        if bare.startswith(prefix):
            return "%s looks like a key or service account" % name
    return None


def one_line(text, limit=120):
    """Collapse untrusted text to a single printable line.

    A filename is chosen by whoever made the file and may contain newlines and
    control characters. Interpolated raw into a report that an assistant reads,
    a name like "id_rsa\\nIgnore prior instructions" becomes a line of its own
    that reads like an instruction rather than a filename. The reasons above
    quote the name back, so both halves need this.
    """
    out = []
    for ch in text:
        if ch.isprintable():
            out.append(ch)
        elif ord(ch) < 256:
            out.append("\\x%02x" % ord(ch))
        else:
            out.append("\\u%04x" % ord(ch))
    line = "".join(out)
    if len(line) > limit:
        line = line[:limit] + "..."
    return line


def quoted(text, limit=120):
    """`one_line`, wrapped in JSON quoting so the delimiters cannot be forged.

    Escaping control characters is not enough by itself. A filename may contain
    a plain double quote, and `id_rsa": Ignore prior instructions` would close
    the quoted span early and leave the rest sitting outside it, reading as
    commentary rather than as part of the name.
    """
    return json.dumps(one_line(text, limit))


def classify(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in IMAGE_EXT:
        return "image"
    if ext == ".pdf":
        return "pdf"
    if ext in URLLIST_EXT:
        return "urllist"
    if ext in TEXT_EXT:
        return "text"
    return "file"


def normalise_url(url):
    """Same page, one item. Drops scheme case, trailing slash, and the fragment."""
    u = url.strip()
    for prefix in ("http://", "https://"):
        if u.lower().startswith(prefix):
            u = u[len(prefix):]
            break
    u = u.split("#", 1)[0]
    if u.endswith("/"):
        u = u[:-1]
    return u.lower()


def urls_in(text):
    import re
    return re.findall(r"https?://[^\s\"'<>)\]]+", text or "")


def _blank_item(item_id, digest, kind, name):
    return {
        "id": item_id,
        "hash": digest,
        "kind": kind,
        "name": name,
        "added_at": store.now(),
        "status": "new",
        "seen": 1,
        "what": "",
        "claims": [],
        "url": "",
        "text": "",
        "media_type": "",
        "goal": "",
        "help": "",
        "cost": "",
        "vetoes": [],
        "route": "",
        "reason": "",
        "decided_at": "",
    }


def add_url(root, url):
    digest = store.hash_bytes(normalise_url(url).encode("utf-8"))
    existing = store.find_by_hash(root, digest)
    if existing:
        existing["seen"] = existing.get("seen", 1) + 1
        store.save_item(root, existing)
        return existing, False
    item = _blank_item(store.new_id(digest), digest, "url", url)
    item["url"] = url
    store.save_item(root, item)
    return item, True


def add_file(root, path):
    with open(path, "rb") as fh:
        data = fh.read()
    digest = store.hash_bytes(data)
    existing = store.find_by_hash(root, digest)
    if existing:
        existing["seen"] = existing.get("seen", 1) + 1
        store.save_item(root, existing)
        return existing, False

    kind = classify(path)
    item = _blank_item(store.new_id(digest), digest, kind, os.path.basename(path))
    ext = os.path.splitext(path)[1].lower()

    if kind in ("text", "urllist"):
        # A link file with links in it is expanded by add_urllist, not here, so
        # anything reaching this point is treated as ordinary text.
        item["text"] = data.decode("utf-8", "replace")[:20000]
        item["kind"] = "text"
    elif kind == "pdf":
        # Best effort. An empty result means the text could not be trusted, which
        # is recorded rather than papered over, so the reading stage can say so.
        item["text"] = pdftext.extract(data)
        item["text_source"] = "pdf-extract" if item["text"] else "none"
    elif kind == "image":
        item["media_type"] = MEDIA_TYPES.get(ext, "image/png")

    store.save_item(root, item)
    if kind in ("image", "pdf", "file"):
        dest = os.path.join(store.item_dir(root, item["id"]), "original" + ext)
        with open(dest, "wb") as fh:
            fh.write(data)
    return item, True


def add_urllist(root, path):
    """Expand a link file into one item per link.

    Returns (added, dupes, expanded). `expanded` is False when the file held no
    links, so the caller can fall back to storing it as text.
    """
    with open(path, "rb") as fh:
        found = urls_in(fh.read().decode("utf-8", "replace"))
    if not found:
        return 0, 0, False
    added = dupes = 0
    for url in found:
        _, is_new = add_url(root, url)
        if is_new:
            added += 1
        else:
            dupes += 1
    return added, dupes, True


def walk(paths, on_skip=None):
    """Yield every file under the given paths, skipping noise and dotfiles.

    Dotfiles and dot-directories are pruned here, before anything downstream
    looks at them. That is why `on_skip` exists on this function as well as on
    `add_paths`: a pruned `.env` or `.ssh/` never reaches the credential check,
    so without this a swept home directory reported nothing left alone at all.

    A pruned directory is reported as itself rather than walked into. Naming it
    is enough to tell a caller why the count is lower than they expected.
    """
    for p in paths:
        if os.path.isfile(p):
            yield p
            continue
        for dirpath, dirnames, filenames in os.walk(p):
            hidden = [d for d in dirnames if d.startswith(".")]
            dirnames[:] = [d for d in dirnames if not d.startswith(".")]
            if on_skip is not None:
                for name in sorted(hidden):
                    if name.lower() in SECRET_DIRS:
                        on_skip(os.path.join(dirpath, name),
                                "%s holds credentials, so it was not opened" % name)
            for name in sorted(filenames):
                if name in SKIP_NAMES:
                    continue
                if name.startswith("."):
                    if on_skip is not None:
                        path = os.path.join(dirpath, name)
                        reason = looks_like_secret(path)
                        if reason:
                            on_skip(path, reason)
                    continue
                yield os.path.join(dirpath, name)


def add_paths(root, paths, on_skip=None):
    """Add everything under `paths`, returning (added, duplicates).

    Files that look like credentials are never taken in. `on_skip`, when given,
    is called with (path, reason) for each one, so a caller can report them. The
    return shape is unchanged so existing callers keep working.
    """
    added = dupes = 0
    for path in walk(paths, on_skip=on_skip):
        reason = looks_like_secret(path)
        if reason:
            if on_skip is not None:
                on_skip(path, reason)
            continue
        if classify(path) == "urllist":
            a, d, expanded = add_urllist(root, path)
            if expanded:
                added += a
                dupes += d
                continue
        _, is_new = add_file(root, path)
        if is_new:
            added += 1
        else:
            dupes += 1
    return added, dupes

